      rc4: { name:'神射协议', desc:'顶点——暴击率+15%、机炮伤害+15%，暴击命中即引爆。' },
      ss1: { name:'战地医疗', desc:'每摧毁一个目标回复5点生命值。' },
      ss2: { name:'虹吸电池', desc:'每次击杀回复5点护盾。' },
      ss3: { name:'再生矩阵', desc:'最大护盾+18、护盾回充+40%，并立即回满。（经续航或装甲抵达。）' },
      ss4: { name:'凤凰核心', desc:'顶点——最大生命值+40、每击杀回复8点，过量治疗转化为额外溢出护盾。' },
      wl1: { name:'战斗节奏', desc:'每点连击增加2%伤害，最高+30%。' },
      wl2: { name:'肾上腺素', desc:'生命值越低伤害越高——濒死时最多+30%伤害。' },
      wl3: { name:'击杀势能', desc:'每次击杀叠加狂热射速，并使世界短暂减速。（经统帅或推进抵达。）' },
      wl4: { name:'征服者', desc:'顶点——得分+25%、全武器伤害+10%，并即时摧毁血量低于12%的非首领目标。' },
